(4747426, 685244, 91405, '<td valign="top">lacks a bit of punch found in other similar photos</td>', 'lacks a bit of punch found in other similar photos', '2008-06-04 05:54:29.000000', NULL, 1),
(4747432, 685125, 91405, '<td valign="top">love it, its different from alot of the other more predictable photos</td>', 'love it, its different from alot of the other more predictable photos', '2008-06-04 05:57:44.000000', NULL, 1),
(4747434, 685351, 91405, '<td valign="top">great shot, one of my favourites</td>', 'great shot, one of my favourites', '2008-06-04 05:58:14.000000', NULL, 1),
(4747436, 685283, 47482, '<td valign="top">wonderfull !</td>', 'wonderfull !', '2008-06-04 05:58:43.000000', NULL, 1),
(4747438, 685125, 47482, '<td valign="top">very majestic and powerful!</td>', 'very majestic and powerful!', '2008-06-04 05:59:01.000000', NULL, 1),
(4747452, 684419, 49111, '<td valign="top">Nice capture, it can be hard to capture the night sky without getting too much noise in the photo, did you use more than one image stacked together?</td>', 'Nice capture, it can be hard to capture the night sky without getting too much noise in the photo, did you use more than one image stacked together?', '2008-06-04 06:19:37.000000', NULL, 1),
(4747453, 683256, 49111, '<td valign="top">Lovely. Even though there is a lot of noise I think that this shot has a lot of character.</td>', 'Lovely. Even though there is a lot of noise I think that this shot has a lot of character.', '2008-06-04 06:20:31.000000', NULL, 1),
(4747455, 685397, 49111, '<td valign="top">The blue really makes this shot stand out and gives it a nice unique look. I am not sure about the bush though, as I find it a little distracting from the main image.</td>', 'The blue really makes this shot stand out and gives it a nice unique look. I am not sure about the bush though, as I find it a little distracting from the main image.', '2008-06-04 06:21:46.000000', NULL, 1),
(4747456, 685244, 49111, '<td valign="top">Thats fantastic, although I would have loved to see a little more contrast or brightness of the star trails (so that are seen better). But other than that nice shot!</td>', 'Thats fantastic, although I would have loved to see a little more contrast or brightness of the star trails (so that are seen better). But other than that nice shot!', '2008-06-04 06:22:59.000000', NULL, 1),
(4747458, 683603, 49111, '<td valign="top">Grat angle and perspective on this shot, I would have liked to see some more of hte stars come through, but that must be hard to do with all those bright city lights.</td>', 'Grat angle and perspective on this shot, I would have liked to see some more of hte stars come through, but that must be hard to do with all those bright city lights.', '2008-06-04 06:24:18.000000', NULL, 1),
(4747460, 685479, 49111, '<td valign="top">The star trails are amazing, and the silhouette of the land makes it more striking</td>', 'The star trails are amazing, and the silhouette of the land makes it more striking', '2008-06-04 06:25:21.000000', NULL, 1),
(4747462, 685354, 49111, '<td valign="top">simply amazing, makes me feel in motion. I like the imposing trees gives it a very strong feel. The swirl of the star trails makes me feel like I am being sucked in. Fab!</td>', 'simply amazing, makes me feel in motion. I like the imposing trees gives it a very strong feel. The swirl of the star trails makes me feel like I am being sucked in. Fab!', '2008-06-04 06:27:30.000000', NULL, 1),
(4747463, 684408, 49111, '<td valign="top">The nebula is a great colour, and those really bright shining stars are very clear and crisp. Great Capture</td>', 'The nebula is a great colour, and those really bright shining stars are very clear and crisp. Great Capture', '2008-06-04 06:28:07.000000', NULL, 1),
(4747464, 685283, 49111, '<td valign="top">The shot is really nicely contrasted with not a lot of noise, the cluster of stars are nicely defined and bright.</td>', 'The shot is really nicely contrasted with not a lot of noise, the cluster of stars are nicely defined and bright.', '2008-06-04 06:29:33.000000', NULL, 1),
(4747465, 685321, 49111, '<td valign="top">The red of the sky is imposing, great colour</td>', 'The red of the sky is imposing, great colour', '2008-06-04 06:30:02.000000', NULL, 1),
(4747466, 683783, 49111, '<td valign="top">Great capture on the lighting strick, nice contrast too. Nature really does look angry here.</td>', 'Great capture on the lighting strick, nice contrast too. Nature really does look angry here.', '2008-06-04 06:31:15.000000', NULL, 1),
(4747468, 685348, 49111, '<td valign="top">Not can I only see it, I can almost feel it. Great capture!</td>', 'Not can I only see it, I can almost feel it. Great capture!', '2008-06-04 06:31:51.000000', NULL, 1),
