(4755146, 683603, 16046, '<td valign="top">nice contrast</td>', 'nice contrast', '2008-06-07 00:33:45.000000', NULL, 1),
(4755150, 684061, 16046, '<td valign="top">Awesome</td>', 'Awesome', '2008-06-07 00:36:40.000000', NULL, 1),
(4755175, 685283, 93001, '<td valign="top">The centering of the subject really doesn''t work for me here.  It doesn''t need that position to draw interest and it removes focus from any other less bright, but interesting, patterns in the sky.</td>', 'The centering of the subject really doesn''t work for me here.  It doesn''t need that position to draw interest and it removes focus from any other less bright, but interesting, patterns in the sky.', '2008-06-07 00:51:01.000000', NULL, 1),
(4755176, 684785, 93001, '<td valign="top">Though I like the shot, I wish it could have been taken from further away, so you wouldn''t have the angles that result from being close to the bottom of a tall object.</td>', 'Though I like the shot, I wish it could have been taken from further away, so you wouldn''t have the angles that result from being close to the bottom of a tall object.', '2008-06-07 00:51:48.000000', NULL, 1),
(4755177, 684916, 93001, '<td valign="top">While that is one spectacular rainbow, it doesn''t feel like a night shot at all.</td>', 'While that is one spectacular rainbow, it doesn''t feel like a night shot at all.', '2008-06-07 00:52:32.000000', NULL, 1),
(4755178, 685129, 87318, '<td valign="top">Very bizzaro kind of cool...</td>', 'Very bizzaro kind of cool...', '2008-06-07 00:54:45.000000', NULL, 1),
(4755208, 685447, 59740, '<td valign="top">Nice exposure of stars and landscape.</td>', 'Nice exposure of stars and landscape.', '2008-06-07 01:29:25.000000', NULL, 1),
