INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4755214, 683701, 59740, '<td valign="top">Would have been more interesting in my opinion if most of the black sky were cropped.</td>', 'Would have been more interesting in my opinion if most of the black sky were cropped.', '2008-06-07 01:33:09.000000', NULL, 1),
