(4755232, 685125, 59740, '<td valign="top">Great capture.</td>', 'Great capture.', '2008-06-07 01:40:02.000000', NULL, 1),
(4755233, 683603, 45032, '<td valign="top">looks like a diamond lit city... beautiful. i''d love to see the pre-photoshop version.</td>', 'looks like a diamond lit city... beautiful. i''d love to see the pre-photoshop version.', '2008-06-07 01:42:21.000000', NULL, 1),
(4755239, 685271, 45032, '<td valign="top">beautiful, awesome catch</td>', 'beautiful, awesome catch', '2008-06-07 01:45:16.000000', NULL, 1),
(4755240, 685125, 45032, '<td valign="top">woah, scary!</td>', 'woah, scary!', '2008-06-07 01:45:41.000000', NULL, 1),
(4755241, 685244, 45032, '<td valign="top">not a big fan of the spinning stars but i love this composition. great shot.</td>', 'not a big fan of the spinning stars but i love this composition. great shot.', '2008-06-07 01:46:20.000000', NULL, 1),
(4755244, 683953, 45032, '<td valign="top">haha, this is how i felt when i went out looking for a night shot, i just gave up, making the most of nothing... great shot.</td>', 'haha, this is how i felt when i went out looking for a night shot, i just gave up, making the most of nothing... great shot.', '2008-06-07 01:47:37.000000', NULL, 1),
(4755321, 684061, 28882, '<td valign="top">amazing!</td>', 'amazing!', '2008-06-07 03:01:03.000000', NULL, 1),
(4755371, 684916, 70689, '<td valign="top">I am not quite sure how this is a <b>night</b> sky, so I will not vote on it. If the pic scores low, that might be beacuse many people think it DNMC. Apart from that, I think it''s a nice rainbow, and you captured it well. The overall colors of the pic seem a bit oversatured. You probably had to, to bring the rainbow out, but it gives the pic an unnatural feel.</td>', 'I am not quite sure how this is a night sky, so I will not vote on it. If the pic scores low, that might be beacuse many people think it DNMC. Apart from that, I think it''s a nice rainbow, and you captured it well. The overall colors of the pic seem a bit oversatured. You probably had to, to bring the rainbow out, but it gives the pic an unnatural feel.', '2008-06-07 04:12:48.000000', NULL, 1),
(4755373, 684371, 70689, '<td valign="top">You may have photographed something special here, although I have no idea what. It sure does have a nightish feel, but I am not too fond of it as a picture. The centered composition and poor IQ (noise, oversaturation, blown highlight) give room for improvement.</td>', 'You may have photographed something special here, although I have no idea what. It sure does have a nightish feel, but I am not too fond of it as a picture. The centered composition and poor IQ (noise, oversaturation, blown highlight) give room for improvement.', '2008-06-07 04:16:21.000000', NULL, 1),
(4755375, 683105, 67237, '<td valign="top">Nice city capture but I do not think THIS night sky improves the composition. I think massive clouds hurt the negative space concept.</td>', 'Nice city capture but I do not think THIS night sky improves the composition. I think massive clouds hurt the negative space concept.', '2008-06-07 04:24:54.000000', NULL, 1),
(4755391, 685351, 15643, '<td valign="top">Absolutly Breathtaking</td>', 'Absolutly Breathtaking', '2008-06-07 05:19:48.000000', NULL, 1),
(4755597, 683603, 35720, '<td valign="top">Excellent, great tones!</td>', 'Excellent, great tones!', '2008-06-07 09:47:40.000000', NULL, 1),
(4755796, 685345, 76335, '<td valign="top">Very minimalist. I think I see a border which only distract from what little is there -- and the fact that it''s only really visible (for me anyway) in one corner. Still, I like the concept and composition.</td>', 'Very minimalist. I think I see a border which only distract from what little is there -- and the fact that it''s only really visible (for me anyway) in one corner. Still, I like the concept and composition.', '2008-06-07 12:12:21.000000', NULL, 1),
(4755799, 685476, 76335, '<td valign="top">This is more about painting with light than anything going on in the sky. Doing this on a clear night might have added some interest. Still, it''s a neat take on the challenge.</td>', 'This is more about painting with light than anything going on in the sky. Doing this on a clear night might have added some interest. Still, it''s a neat take on the challenge.', '2008-06-07 12:14:29.000000', NULL, 1),
(4755801, 683883, 76335, '<td valign="top">It''s a beautiful image, but not really about the night sky in my opinion. Love the colors.</td>', 'It''s a beautiful image, but not really about the night sky in my opinion. Love the colors.', '2008-06-07 12:15:02.000000', NULL, 1),
(4755961, 683137, 76335, '<td valign="top">Interesting, but the light show in the foreground steals the show -- the night sky becomes just an elaborate background. Challenge aside, it''s a really cool image.</td>', 'Interesting, but the light show in the foreground steals the show -- the night sky becomes just an elaborate background. Challenge aside, it''s a really cool image.', '2008-06-07 13:46:43.000000', NULL, 1),
(4755987, 683701, 76335, '<td valign="top">A night scene for sure, but not really about the sky.</td>', 'A night scene for sure, but not really about the sky.', '2008-06-07 13:53:11.000000', NULL, 1),
(4755988, 685090, 76335, '<td valign="top">An original idea if anything. Like the title.</td>', 'An original idea if anything. Like the title.', '2008-06-07 13:53:34.000000', NULL, 1),
(4755994, 685459, 76335, '<td valign="top">Neat stuff going on. Somewhat disorienting. Curious framing.</td>', 'Neat stuff going on. Somewhat disorienting. Curious framing.', '2008-06-07 13:55:04.000000', NULL, 1),
(4755998, 685384, 76335, '<td valign="top">Great contrast and an original take on the challenge. Somewhat edgy, slightly ominous.</td>', 'Great contrast and an original take on the challenge. Somewhat edgy, slightly ominous.', '2008-06-07 13:56:51.000000', NULL, 1),
(4756021, 685314, 76335, '<td valign="top">But no smoke on the water? Nice!</td>', 'But no smoke on the water? Nice!', '2008-06-07 14:03:28.000000', NULL, 1),
(4756022, 683965, 76335, '<td valign="top">A Tums will take care of that, Leo. Just kidding. I like this a lot -- especially your decision to show this relative to Earth objects.</td>', 'A Tums will take care of that, Leo. Just kidding. I like this a lot -- especially your decision to show this relative to Earth objects.', '2008-06-07 14:03:33.000000', NULL, 1),
(4756023, 684742, 76335, '<td valign="top">Lots of drama. Nice. I''ll be curious to read how you exposed this.</td>', 'Lots of drama. Nice. I''ll be curious to read how you exposed this.', '2008-06-07 14:03:35.000000', NULL, 1),
(4756583, 685125, 79720, '<td valign="top">Simply awesome.</td>', 'Simply awesome.', '2008-06-07 20:05:20.000000', NULL, 1),
(4756594, 684742, 69246, '<td valign="top">I love the use of the small aperature. I also like the jet in the upper left.</td>', 'I love the use of the small aperature. I also like the jet in the upper left.', '2008-06-07 20:10:34.000000', NULL, 1),
(4756598, 685461, 69246, '<td valign="top">Nice capture of the milky way. Too bad too much light pollution for the gegenshein.</td>', 'Nice capture of the milky way. Too bad too much light pollution for the gegenshein.', '2008-06-07 20:11:27.000000', NULL, 1),
(4756603, 684798, 69246, '<td valign="top">Never summer range? Looks like 45° latitude...can''t wait to see the location.</td>', 'Never summer range? Looks like 45° latitude...can''t wait to see the location.', '2008-06-07 20:13:20.000000', NULL, 1),
