(4763659, 685345, 50695, '<td valign="top">Awesome!</td>', 'Awesome!', '2008-06-11 10:57:56.000000', NULL, 0),
(4763706, 683603, 60862, '<td valign="top">Congrats, Enzo!  I have to admit I wavered on the night sky DNMC, but ended up deciding it was an important part of the image and gave it an 8.  I also love the light flare that seems to connect the city to the sky.</td>', 'Congrats, Enzo!  I have to admit I wavered on the night sky DNMC, but ended up deciding it was an important part of the image and gave it an 8.  I also love the light flare that seems to connect the city to the sky.', '2008-06-11 11:11:21.000000', NULL, 0),
