(4764091, 685125, 52549, '<td valign="top">Wow! Now that''s what I call a GOOD score ;-) Big congrats on winning with this amazingly beautiful image.</td>', 'Wow! Now that''s what I call a GOOD score ;-) Big congrats on winning with this amazingly beautiful image.', '2008-06-11 13:59:43.000000', NULL, 0),
(4764101, 683603, 52549, '<td valign="top">WTG, Enzo!! I LOVE your blues and greys. 7.7!!! My goodness, this must be the highest red ribbon score ever, congratulations. Btw, I see you''re not getting any better at predicting your scores ;-D</td>', 'WTG, Enzo!! I LOVE your blues and greys. 7.7!!! My goodness, this must be the highest red ribbon score ever, congratulations. Btw, I see you''re not getting any better at predicting your scores ;-D', '2008-06-11 14:02:58.000000', NULL, 0),
