(4764153, 685397, 52549, '<td valign="top">Very beautiful image, Brian. Congratulations on top 20 in this very difficult challenge.</td>', 'Very beautiful image, Brian. Congratulations on top 20 in this very difficult challenge.', '2008-06-11 14:27:36.000000', NULL, 0),
(4764191, 685310, 52549, '<td valign="top">Thanks for the Scottish sunset, it warmed my heart.</td>', 'Thanks for the Scottish sunset, it warmed my heart.', '2008-06-11 14:46:13.000000', NULL, 0),
(4764198, 685479, 44825, '<td valign="top">I think that this shot was a real winner and deserved a much higher placing. even more so after reading about your time constraint! Well done!</td>', 'I think that this shot was a real winner and deserved a much higher placing. even more so after reading about your time constraint! Well done!', '2008-06-11 14:47:59.000000', NULL, 0),
(4764208, 684061, 39850, '<td valign="top">I gave this a 7 (the pines mainly), alas I was #81 and my vote was ''scrubbed'' due to my ''call'' on most of the other entries.  All I can say (and hope for) is that one day they have an Astrophotography Challenge - maybe then, maybe, an authentic image such as this will be able to take the throne.  Anyway, congratulations on the ribbon.  I also hope those with the knowledge give you some feedback on your tutorial, <a href="//www.geocities.com/bedfordnights/widefieldtutorial.html" rel="nofollow" target="_blank">widefield astrophotography</a>.  I mistook <a href="//www.dpchallenge.com/image.php?IMAGE_ID=684408" rel="nofollow" target="_blank">Eagle Nebula, M16</a> for yours.  However it is good to see more of this photography at DPC.  Thank you again for sharing, some of us really appreciate these images and this style of photography.</td>', 'I gave this a 7 (the pines mainly), alas I was #81 and my vote was ''scrubbed'' due to my ''call'' on most of the other entries.  All I can say (and hope for) is that one day they have an Astrophotography Challenge - maybe then, maybe, an authentic image such as this will be able to take the throne.  Anyway, congratulations on the ribbon.  I also hope those with the knowledge give you some feedback on your tutorial, widefield astrophotography.  I mistook Eagle Nebula, M16 for yours.  However it is good to see more of this photography at DPC.  Thank you again for sharing, some of us really appreciate these images and this style of photography.', '2008-06-11 14:52:25.000000', NULL, 0),
(4764219, 684408, 39850, '<td valign="top">Apologies for mistaking you for <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=84124" rel="nofollow" target="_blank">jlanoue</a>, although surely it is not an insult.  Disappointed of course this didn''t ribbon - maybe one day there will be an Astrophotography Challenge.  Maybe.  Thank you for sharing these at DPC.</td>', 'Apologies for mistaking you for  jlanoue, although surely it is not an insult.  Disappointed of course this didn''t ribbon - maybe one day there will be an Astrophotography Challenge.  Maybe.  Thank you for sharing these at DPC.', '2008-06-11 14:55:46.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4764296, 684061, 84438, '<td valign="top">All I have to say is: <b>It''s about time</b> that you got the recognition you deserve from the voters.  Congrats on the ribbon..  It''s well deserved.</td>', 'All I have to say is: It''s about time that you got the recognition you deserve from the voters.  Congrats on the ribbon..  It''s well deserved.', '2008-06-11 15:29:07.000000', NULL, 0),
